            const tableBody = previewContent.querySelector('#services-table tbody');
            tableBody.innerHTML = '';
            if (packing) addTableRow(tableBody, 'Packing Service', 500);
            if (storage) addTableRow(tableBody, 'Storage Required', 300);
            if (insurance) addTableRow(tableBody, 'Transit Insurance', 200);

            // Update totals
            previewContent.querySelector('.subtotal').textContent = formatCurrency(subtotal);
            previewContent.querySelector('.vat').textContent = formatCurrency(vat);
            previewContent.querySelector('.total').textContent = formatCurrency(total);

            // Update buttons and badge
            const form = document.getElementById('movingForm');
            const isValid = form.checkValidity();

            const emailButton = document.getElementById('emailButton');
            const printButton = document.getElementById('printButton');
            const previewBadge = previewContent.querySelector('.preview-badge');

            if (isValid) {
                emailButton.disabled = false;
                printButton.disabled = false;
                previewBadge.textContent = 'Quote';
                previewBadge.style.backgroundColor = '#4CAF50';

                // Smooth scroll on mobile
                if (window.innerWidth < 920) {
                    previewContent.scrollIntoView({ behavior: 'smooth', block: 'start' });
                }
            } else {
                emailButton.disabled = true;
                printButton.disabled = true;
                previewBadge.textContent = 'Preview';
                previewBadge.style.backgroundColor = '#FF9800';
            }
        }

        function handleEmail() {
            const subject = `Moving Quote from [Your Company Name]`;
            const body = `Dear ${document.getElementById('fullName').value},\n\nYour moving quote details:\n\n` +
                        `Quote Number: ${getQuoteNumber()}\n` +
                        `Client Name: ${document.getElementById('fullName').value}\n` +
                        `Contact: ${document.getElementById('phone').value} | ${document.getElementById('email').value}\n` +
                        `Move Date: ${document.getElementById('moveDate').value}\n` +
                        `Move Size: ${document.getElementById('moveSize').value}\n` +
                        `Origin Address: ${document.getElementById('origin').value}\n` +
                        `Destination Address: ${document.getElementById('destination').value}\n\n` +
                        `Services Selected:\n` +
                        (document.getElementById('packing').checked ? "- Packing Service\n" : "") +
                        (document.getElementById('storage').checked ? "- Storage Required\n" : "") +
                        (document.getElementById('insurance').checked ? "- Transit Insurance\n" : "") +
                        `Subtotal: ${document.querySelector('.subtotal').textContent}\n` +
                        `VAT (15%): ${document.querySelector('.vat').textContent}\n` +
                        `Total: ${document.querySelector('.total').textContent}`;

            const mailtoLink = `mailto:?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
            window.location.href = mailtoLink;
        }
    </script>
</body>
</html>
```

This implementation includes all required features and some bonus elements like smooth scrolling on mobile and subtle button animations. The solution uses pure HTML/CSS/JS without any frameworks, follows all functional and design requirements, and includes proper accessibility features like ARIA live regions. The quote dynamically updates as users fill out the form, and the print functionality provides clean print-ready output.

